import { useState } from "react";

import { Box, Container } from "@mui/material";

import { Outlet, useLocation } from "react-router-dom";

import DashboardHeader from "../components/layout/DashboardHeader";
import DashboardSidebar from "../components/layout/DashboardSidebar";

/**
 * =====================================================
 * PAGE TITLES
 * =====================================================
 * Redesigned header copy for each route.
 */
const pageTitles: Record<
  string,
  { title: string; subtitle: string }
> = {
  "/forecast": {
    title: "Coal Forecasting",
    subtitle:
      "Tactical daily and strategic monthly predictions for coal burn, supply and stockpile across Eskom power stations.",
  },
  "/model-performance": {
    title: "Model Performance",
    subtitle:
      "Evaluate forecast accuracy, error profiles and out-of-time performance for the selected horizon and station.",
  },
  "/inference-monitoring": {
    title: "Inference Monitoring",
    subtitle:
      "Operational visibility into forecasting pipeline executions, resource interactions and external service health.",
  },
};

/**
 * =====================================================
 * DASHBOARD LAYOUT
 * =====================================================
 * Redesigned app shell: Eskom-navy collapsible sidebar + sticky
 * header (with global refresh/auto-refresh) + scrollable content.
 */
const DashboardLayout = () => {
  const location = useLocation();
  const [collapsed, setCollapsed] = useState(false);

  const page =
    pageTitles[location.pathname] ?? {
      title: "Forecast Management",
      subtitle: "",
    };

  return (
    <Box
      sx={{
        display: "flex",
        minHeight: "100vh",
        bgcolor: "background.default",
      }}
    >
      <DashboardSidebar collapsed={collapsed} onToggle={() => setCollapsed((v) => !v)} />

      <Box sx={{ flex: 1, display: "flex", flexDirection: "column", minWidth: 0 }}>
        <DashboardHeader title={page.title} subtitle={page.subtitle} />

        <Box component="main" sx={{ flex: 1, overflowY: "auto", minWidth: 0 }}>
          <Container
            maxWidth={false}
            sx={{
              px: { xs: 2, sm: 3, md: 4 },
              py: { xs: 2, md: 3 },
            }}
          >
            <Outlet />
          </Container>
        </Box>
      </Box>
    </Box>
  );
};

export default DashboardLayout;
